-- Initial schema. See docs/backend-design.md, "Persistence and ownership".
-- Timestamps are ISO-8601 UTC text. IDs are opaque text generated by the backend.
-- The vector table (sqlite-vec) is added by a later migration once the extension is wired in.

CREATE TABLE albums (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL UNIQUE COLLATE NOCASE,
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL
);

-- One row and one original object per distinct byte sequence.
-- Metadata columns stay NULL when the file does not carry them; never filled with guesses.
CREATE TABLE assets (
  id              TEXT PRIMARY KEY,
  sha256          TEXT NOT NULL UNIQUE,
  object_key      TEXT NOT NULL,
  format          TEXT NOT NULL,   -- detected by magic bytes: jpeg, png, heic, avif, ...
  mime            TEXT NOT NULL,
  byte_size       INTEGER NOT NULL,
  width           INTEGER,
  height          INTEGER,
  derivative_key  TEXT,
  thumbnail_key   TEXT,
  taken_at        TEXT,
  camera_make     TEXT,
  camera_model    TEXT,
  gps_lat         REAL,
  gps_lon         REAL,
  created_at      TEXT NOT NULL,
  orphaned_at     TEXT             -- set when the last membership is removed
);
CREATE INDEX assets_orphaned_at ON assets (orphaned_at) WHERE orphaned_at IS NOT NULL;
CREATE INDEX assets_taken_at ON assets (taken_at) WHERE taken_at IS NOT NULL;
CREATE INDEX assets_camera_model ON assets (camera_model) WHERE camera_model IS NOT NULL;

CREATE TABLE album_assets (
  album_id          TEXT NOT NULL REFERENCES albums (id) ON DELETE CASCADE,
  asset_id          TEXT NOT NULL REFERENCES assets (id) ON DELETE CASCADE,
  display_filename  TEXT NOT NULL,
  added_at          TEXT NOT NULL,
  PRIMARY KEY (album_id, asset_id)
);
CREATE INDEX album_assets_asset ON album_assets (asset_id);
CREATE INDEX album_assets_album_added ON album_assets (album_id, added_at);

-- Effective caption = manual_caption when present, else ai_caption.
CREATE TABLE descriptions (
  asset_id          TEXT PRIMARY KEY REFERENCES assets (id) ON DELETE CASCADE,
  ai_caption        TEXT,
  ai_tags           TEXT NOT NULL DEFAULT '[]',  -- JSON array of strings
  manual_caption    TEXT,
  provider          TEXT,                         -- deepseek | openai
  model             TEXT,
  prompt_revision   INTEGER,
  enrichment_state  TEXT NOT NULL DEFAULT 'none'
                    CHECK (enrichment_state IN ('none', 'pending', 'done', 'failed')),
  updated_at        TEXT NOT NULL
);

CREATE TABLE import_jobs (
  id             TEXT PRIMARY KEY,
  kind           TEXT NOT NULL CHECK (kind IN ('folder', 'files')),
  album_id       TEXT REFERENCES albums (id) ON DELETE SET NULL,
  source_label   TEXT NOT NULL,   -- folder basename or "N selected files"; never a full path
  state          TEXT NOT NULL DEFAULT 'queued'
                 CHECK (state IN ('queued', 'running', 'paused', 'completed', 'failed', 'canceled')),
  intake_closed  INTEGER NOT NULL DEFAULT 0,
  created_at     TEXT NOT NULL,
  updated_at     TEXT NOT NULL
);

CREATE TABLE import_items (
  id                TEXT PRIMARY KEY,
  job_id            TEXT NOT NULL REFERENCES import_jobs (id) ON DELETE CASCADE,
  item_key          TEXT NOT NULL,   -- relative path within the folder, or manifest entry key
  display_filename  TEXT NOT NULL,
  byte_size         INTEGER,
  state             TEXT NOT NULL DEFAULT 'pending'
                    CHECK (state IN ('pending', 'running', 'imported', 'skipped', 'failed')),
  reason            TEXT,            -- duplicate_in_album, unsupported_format, too_large, ...
  asset_id          TEXT REFERENCES assets (id) ON DELETE SET NULL,
  updated_at        TEXT NOT NULL,
  UNIQUE (job_id, item_key)
);
CREATE INDEX import_items_job_state ON import_items (job_id, state);

CREATE TABLE processing_tasks (
  id               TEXT PRIMARY KEY,
  asset_id         TEXT NOT NULL REFERENCES assets (id) ON DELETE CASCADE,
  kind             TEXT NOT NULL CHECK (kind IN ('caption', 'embedding', 'enrichment')),
  revision         INTEGER NOT NULL DEFAULT 1,
  state            TEXT NOT NULL DEFAULT 'pending'
                   CHECK (state IN ('pending', 'running', 'succeeded', 'failed')),
  attempts         INTEGER NOT NULL DEFAULT 0,
  next_attempt_at  TEXT,
  error            TEXT,
  provider         TEXT,
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL,
  UNIQUE (asset_id, kind, revision)
);
CREATE INDEX processing_tasks_queue ON processing_tasks (kind, state, next_attempt_at);

-- No foreign key: the asset row is already gone when its n8n row must be deleted.
CREATE TABLE n8n_purge_queue (
  asset_id         TEXT PRIMARY KEY,
  requested_at     TEXT NOT NULL,
  attempts         INTEGER NOT NULL DEFAULT 0,
  next_attempt_at  TEXT
);

CREATE TABLE export_jobs (
  id          TEXT PRIMARY KEY,
  scope       TEXT NOT NULL,   -- JSON: {"albumIds":[...]} or {"assetIds":[...]}
  state       TEXT NOT NULL DEFAULT 'queued'
              CHECK (state IN ('queued', 'running', 'completed', 'failed', 'canceled')),
  total       INTEGER NOT NULL DEFAULT 0,
  done        INTEGER NOT NULL DEFAULT 0,
  zip_key     TEXT,
  expires_at  TEXT,
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL
);

-- Single-row settings. API keys and the webhook secret are never returned to the browser or logs.
CREATE TABLE model_config (
  id                       INTEGER PRIMARY KEY CHECK (id = 1),
  deepseek_base_url        TEXT NOT NULL DEFAULT 'https://api.deepseek.com',
  deepseek_model           TEXT NOT NULL DEFAULT 'deepseek-flash',
  deepseek_api_key         TEXT,
  openai_base_url          TEXT NOT NULL DEFAULT 'https://api.openai.com/v1',
  openai_model             TEXT,
  openai_api_key           TEXT,
  openai_fallback_enabled  INTEGER NOT NULL DEFAULT 0,
  n8n_webhook_url          TEXT,
  n8n_webhook_secret       TEXT,
  default_search_mode      TEXT NOT NULL DEFAULT 'words'
                           CHECK (default_search_mode IN ('words', 'meaning', 'both')),
  caption_concurrency      INTEGER NOT NULL DEFAULT 4,
  enrichment_concurrency   INTEGER NOT NULL DEFAULT 2,
  updated_at               TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
INSERT INTO model_config (id) VALUES (1);

-- Written once when the vector index is created; guards against mixing models.
CREATE TABLE embedding_meta (
  id          INTEGER PRIMARY KEY CHECK (id = 1),
  model_id    TEXT NOT NULL,
  revision    TEXT NOT NULL,
  dimension   INTEGER NOT NULL,
  created_at  TEXT NOT NULL
);

CREATE TABLE idempotency_keys (
  key          TEXT PRIMARY KEY,
  operation    TEXT NOT NULL,
  fingerprint  TEXT NOT NULL,
  response     TEXT NOT NULL,   -- JSON: {"status":..., "body":...}
  created_at   TEXT NOT NULL
);

-- Lexical search over effective caption, tags, and membership filenames.
CREATE VIRTUAL TABLE photo_fts USING fts5 (
  asset_id UNINDEXED,
  caption,
  tags,
  filenames,
  tokenize = 'unicode61 remove_diacritics 2',
  prefix = '2 3'
);
